import { createHash, createHmac } from 'node:crypto';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { env } from '../config/env.js';

/**
 * Private store of teacher application documents (identity documents, diplomas, CVs). Files are never stored in MongoDB nor
 * served from a public path: the API reads them back for an authorised request only. Keys are generated by the server.
 */
export interface DocumentStore {
  readonly kind: 'local' | 's3';
  /** False when files could be lost on restart (local disk of an ephemeral host): final submissions are then refused. */
  readonly persistent: boolean;
  put(key: string, body: Buffer, mimeType: string): Promise<void>;
  get(key: string): Promise<Buffer>;
  remove(key: string): Promise<void>;
}

export class DocumentStoreError extends Error {
  constructor(public code: 'NOT_FOUND' | 'UNAVAILABLE') { super(code); }
}

const KEY = /^[a-f0-9]{32}\.(pdf|png|jpg)$/;
const checkKey = (key: string) => { if (!KEY.test(key)) throw new Error('INVALID_DOCUMENT_KEY'); };

class LocalDocumentStore implements DocumentStore {
  readonly kind = 'local' as const;
  private readonly root = path.resolve(env.PRIVATE_UPLOAD_DIR, 'teacher-applications');
  // Development store, or a persistent disk explicitly declared by the operator (e.g. a mounted volume).
  readonly persistent = env.NODE_ENV !== 'production' || env.PRIVATE_UPLOAD_PERSISTENT === 'true';

  async put(key: string, body: Buffer) { checkKey(key); await mkdir(this.root, { recursive: true }); await writeFile(path.join(this.root, key), body, { flag: 'wx', mode: 0o600 }); }
  async get(key: string) {
    checkKey(key);
    try { return await readFile(path.join(this.root, key)); } catch { throw new DocumentStoreError('NOT_FOUND'); }
  }
  async remove(key: string) { checkKey(key); await rm(path.join(this.root, key), { force: true }); }
}

const sha256 = (value: Buffer | string) => createHash('sha256').update(value).digest('hex');
const hmac = (key: Buffer | string, value: string) => createHmac('sha256', key).update(value).digest();
const encodeSegment = (segment: string) => encodeURIComponent(segment).replace(/[!'()*]/g, char => `%${char.charCodeAt(0).toString(16).toUpperCase()}`);

export const amzDateOf = (date: Date) => date.toISOString().replace(/[:-]|\.\d{3}/g, '');

/** AWS Signature Version 4 `Authorization` header (S3 flavour: the URI is encoded once, the payload hash is a header). */
export function signV4(input: { method: string; url: URL; headers: Record<string, string>; payloadHash: string; region: string; accessKeyId: string; secretAccessKey: string; date: Date }) {
  const amzDate = amzDateOf(input.date);
  const day = amzDate.slice(0, 8);
  const headers = Object.fromEntries(Object.entries({ ...input.headers, host: input.url.host }).map(([name, value]) => [name.toLowerCase(), value.trim().replace(/\s+/g, ' ')]));
  const signedHeaders = Object.keys(headers).sort();
  const canonicalUri = input.url.pathname.split('/').map(segment => encodeSegment(decodeURIComponent(segment))).join('/');
  const canonicalQuery = [...input.url.searchParams.entries()].map(([name, value]) => `${encodeSegment(name)}=${encodeSegment(value)}`).sort().join('&');
  const canonical = [input.method, canonicalUri, canonicalQuery, signedHeaders.map(name => `${name}:${headers[name]}\n`).join(''), signedHeaders.join(';'), input.payloadHash].join('\n');
  const scope = `${day}/${input.region}/s3/aws4_request`;
  const toSign = ['AWS4-HMAC-SHA256', amzDate, scope, sha256(canonical)].join('\n');
  const signingKey = hmac(hmac(hmac(hmac(`AWS4${input.secretAccessKey}`, day), input.region), 's3'), 'aws4_request');
  const signature = createHmac('sha256', signingKey).update(toSign).digest('hex');
  return `AWS4-HMAC-SHA256 Credential=${input.accessKeyId}/${scope}, SignedHeaders=${signedHeaders.join(';')}, Signature=${signature}`;
}

/** Any S3-compatible private bucket (AWS S3, Cloudflare R2, Backblaze B2, MinIO…). Objects are written without public ACL. */
class S3DocumentStore implements DocumentStore {
  readonly kind = 's3' as const;
  readonly persistent = true;

  private objectUrl(key: string) {
    checkKey(key);
    const objectKey = `${env.S3_PREFIX}${key}`.split('/').map(encodeSegment).join('/');
    const endpoint = new URL(env.S3_ENDPOINT || `https://s3.${env.S3_REGION}.amazonaws.com`);
    if (env.S3_FORCE_PATH_STYLE === 'true') return new URL(`${endpoint.origin}/${env.S3_BUCKET}/${objectKey}`);
    return new URL(`${endpoint.protocol}//${env.S3_BUCKET}.${endpoint.host}/${objectKey}`);
  }

  private async request(method: 'PUT' | 'GET' | 'DELETE', key: string, body?: Buffer, mimeType?: string) {
    const url = this.objectUrl(key);
    const payloadHash = sha256(body || '');
    const now = new Date();
    const headers: Record<string, string> = { 'x-amz-content-sha256': payloadHash, 'x-amz-date': amzDateOf(now) };
    if (body) { headers['content-type'] = mimeType || 'application/octet-stream'; headers['content-length'] = String(body.length); }
    const authorization = signV4({ method, url, headers, payloadHash, region: env.S3_REGION, accessKeyId: env.S3_ACCESS_KEY_ID!, secretAccessKey: env.S3_SECRET_ACCESS_KEY!, date: now });
    let response: Response;
    try { response = await fetch(url, { method, headers: { ...headers, authorization }, body: body ? new Uint8Array(body) : undefined, signal: AbortSignal.timeout(20_000) }); }
    catch { throw new DocumentStoreError('UNAVAILABLE'); }
    if (response.status === 404) throw new DocumentStoreError('NOT_FOUND');
    // The response body may describe the bucket: it is not logged nor returned.
    if (!response.ok) throw new DocumentStoreError('UNAVAILABLE');
    return response;
  }

  async put(key: string, body: Buffer, mimeType: string) { await this.request('PUT', key, body, mimeType); }
  async get(key: string) { return Buffer.from(await (await this.request('GET', key)).arrayBuffer()); }
  async remove(key: string) { try { await this.request('DELETE', key); } catch (error) { if ((error as DocumentStoreError).code !== 'NOT_FOUND') throw error; } }
}

let store: DocumentStore = env.TEACHER_DOCUMENTS_STORAGE === 's3' ? new S3DocumentStore() : new LocalDocumentStore();
export const documentStore = () => store;

/** Tests only (refused in production): an in-memory or failing store. */
export function replaceDocumentStoreForTests(replacement: DocumentStore | null) {
  if (env.NODE_ENV === 'production') throw new Error('Document store replacement is test-only.');
  store = replacement || (env.TEACHER_DOCUMENTS_STORAGE === 's3' ? new S3DocumentStore() : new LocalDocumentStore());
}
